import React from 'react';

import {
  IQuestion,
  IQuestionDirWithAnswer,
  IQuestionInputWithAnswer,
  IQuestionSelectWithAnswer,
  IQuestionType,
  IQuestionWithAnswer,
} from '@apps/Interview/@types/interview.types';
import PohCard from '@ui-kit/Card';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import QuestionDir from './QuestionDir';
import QuestionInput from './QuestionInput';
import QuestionSelect from './QuestionSelect';

interface IQuestionForAnswerProps extends React.HTMLAttributes<HTMLDivElement> {
  item: IQuestion;
  result?: IQuestionWithAnswer;
  disabled?: boolean;
}

const QuestionForAnswer: React.FC<IQuestionForAnswerProps> = ({
  item,
  disabled,
  children,
  result,
}) => {
  return (
    <PohCard className="mb-1">
      <PohRow>
        <PohCol sm="2">
          <strong className="me-2 " title={item.name}>
            {item.name}
            <sup className="text-danger">{item.isRequire && '*'}</sup>
          </strong>
        </PohCol>
        <PohCol sm="10">
          {item.type === IQuestionType.Input && (
            <QuestionInput
              data={item}
              result={result as IQuestionInputWithAnswer}
              disabled={disabled}
            />
          )}
          {item.type === IQuestionType.Select && (
            <QuestionSelect
              data={item}
              result={result as IQuestionSelectWithAnswer}
              disabled={disabled}
            />
          )}
          {item.type === IQuestionType.Dir && (
            <QuestionDir
              data={item}
              result={result as IQuestionDirWithAnswer}
              disabled={disabled}
            />
          )}

          {children}
        </PohCol>
      </PohRow>
    </PohCard>
  );
};

export default QuestionForAnswer;
