import React from 'react';

import { IQuestionSelect, IQuestionSelectWithAnswer } from '@apps/Interview/@types/interview.types';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput from '@ui-kit/Input';
import PohList from '@ui-kit/List';
import PohRadio from '@ui-kit/Radio';

interface IQuestionSelectProps {
  data: IQuestionSelect;
  result?: IQuestionSelectWithAnswer;
  disabled?: boolean;
}

const QuestionSelect: React.FC<IQuestionSelectProps> = ({ data, disabled, result }) => {
  const [checked, setChecked] = React.useState<string[]>([]);
  const [cus, setCus] = React.useState<string>('');

  return (
    <div>
      <PohList
        data={data.options.map((x) => {
          return {
            key: x.id,
            children: data.isMulti ? (
              <PohCheckbox
                label={x.value}
                disabled={disabled}
                required={checked.length === 0 && !data.isCustom}
                name={`${data.id}`}
                data-value={x.id}
                checked={result?.selectedIds.includes(x.id) || checked.includes(x.value)}
                defaultChecked={result?.selectedIds.includes(x.id)}
                onChange={(ch) =>
                  setChecked((cur) => (ch ? [...cur, x.value] : cur.filter((c) => c !== x.value)))
                }
              />
            ) : (
              <PohRadio
                label={x.value}
                disabled={disabled}
                name={`${data.id}`}
                required={data.isRequire}
                data-value={x.id}
                defaultChecked={result?.selectedIds.includes(x.id)}
              />
            ),
          };
        })}
      />
      {data.isCustom && data.isMulti && (
        <PohInput
          defaultValue={result?.customValue ?? ''}
          className="mt-3"
          disabled={disabled}
          placeholder={'Свой вариант'}
          required={checked.length === 0}
          value={cus}
          onChange={setCus}
          name={`${data.id}-custom`}
        />
      )}
      <div>
        <small>{data.text}</small>
      </div>
    </div>
  );
};

export default QuestionSelect;
