import React from 'react';

import { IQuestionInput, IQuestionInputWithAnswer } from '@apps/Interview/@types/interview.types';
import PohInput, { InputTypes } from '@ui-kit/Input';

interface IQuestionInputProps {
  data: IQuestionInput;
  result?: IQuestionInputWithAnswer;
  disabled?: boolean;
}

const QuestionInput: React.FC<IQuestionInputProps> = ({ data, disabled, result }) => {
  return (
    <div>
      <PohInput
        defaultValue={result?.value ?? ''}
        disabled={disabled}
        type={data.params.type as InputTypes}
        placeholder={data.params.placeholder}
        pattern={data.params.pattern ? data.params.pattern : undefined}
        min={data.params.min}
        max={data.params.max}
        step={data.params.step ? +data.params.step : undefined}
        required={data.isRequire}
        name={`${data.id}`}
        message={
          <div>
            <small>{data.text}</small>
          </div>
        }
        wrapperClassName="w-100"
      />
    </div>
  );
};

export default QuestionInput;
