import React from 'react';

import cn from 'clsx';

import { uniqueId } from '@helpers/unuqueId';

export enum RadioLabelPosition {
  Before,
  After,
}

interface IPohRadioProps extends Omit<React.HTMLAttributes<HTMLInputElement>, 'onChange'> {
  labelPosition?: RadioLabelPosition;
  label?: React.ReactNode;
  id?: string;
  checked?: boolean;
  disabled?: boolean;
  inline?: boolean;
  required?: boolean;
  name: string;
  onChange?: (checked: boolean, e: React.ChangeEvent<HTMLInputElement>) => void;
}

const PohRadio: React.FC<IPohRadioProps> = ({
  className,
  label,
  id,
  labelPosition = RadioLabelPosition.After,
  onChange,
  name,
  inline = false,
  ...rest
}) => {
  const uId = id || uniqueId('pohCheckbox');
  return (
    <div className={cn('form-check', { 'form-check-inline': inline })}>
      {label && labelPosition === RadioLabelPosition.Before && (
        <label className="form-check-label" htmlFor={uId}>
          {label}
        </label>
      )}
      <input
        type="radio"
        name={name}
        id={uId}
        className={cn('form-check-input', { 'position-static': !label }, className)}
        onChange={(event) => onChange?.(event.target.checked, event)}
        {...rest}
      />
      {label && labelPosition === RadioLabelPosition.After && (
        <label className="form-check-label" htmlFor={uId}>
          {label}
        </label>
      )}
    </div>
  );
};

export default PohRadio;
